import { useContext, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import { useNavigate } from 'react-router-dom';
import api from '../../api/axios'; // Use custom Axios instance
import './post.scss';

const Post = ({ post }) => {
  const { currentUser } = useContext(AuthContext);
  const [error, setError] = useState(null);
  const [commentInput, setCommentInput] = useState('');
  const navigate = useNavigate();

  const getMediaUrl = (media) => {
    if (!media) {
      console.log('Post: No media provided, using fallback');
      return 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
    }
    if (media.startsWith('http')) {
      console.log('Post: Using external media URL:', media);
      return media;
    }
    const normalizedPath = media.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Post: Generated media URL:', url);
    return url;
  };

  const handleLike = async () => {
    try {
      const token = sessionStorage.getItem('token');
      if (!token) {
        console.error('Post: No token found');
        navigate('/login');
        return;
      }
      console.log(`Post: Toggling like for post ${post._id} with token:`, token.substring(0, 10) + '...');
      const res = await api.post(
        `/posts/${post._id}/like`,
        { userId: currentUser._id },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      console.log(`Post: Like response:`, res.data);
      window.dispatchEvent(new Event('newPost')); // Trigger refresh
      setError(null);
    } catch (err) {
      console.error('Post: Error toggling like:', err.message, err.response?.data);
      setError(err.response?.data?.message || 'Failed to like post');
    }
  };

  const handleCommentSubmit = async (e) => {
    e.preventDefault();
    const content = commentInput.trim();
    if (!content) {
      setError('Comment cannot be empty');
      return;
    }

    try {
      const token = sessionStorage.getItem('token');
      if (!token) {
        console.error('Post: No token found');
        navigate('/login');
        return;
      }
      console.log(`Post: Submitting comment for post ${post._id}: ${content} with token:`, token.substring(0, 10) + '...');
      const res = await api.post(
        `/posts/${post._id}/comment`,
        { userId: currentUser._id, content },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      console.log(`Post: Comment response:`, res.data);
      window.dispatchEvent(new Event('newPost')); // Trigger refresh
      setCommentInput('');
      setError(null);
    } catch (err) {
      console.error('Post: Error submitting comment:', err.message, err.response?.data);
      setError(err.response?.data?.message || 'Failed to add comment');
    }
  };

  return (
    <div className="post">
      <div className="post-header">
        <img
          src={getMediaUrl(post.userId?.profilePicture)}
          alt={`${post.name}'s profile`}
          className="post-avatar"
          onError={(e) => {
            console.error(`Post: Profile picture load error for ${post.name}:`, e);
            e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
          }}
        />
        <div className="post-info">
          <span className="name">{post.name || 'Unknown User'}</span>
          <span className="timestamp">
            {new Date(post.createdAt).toLocaleString()}
          </span>
        </div>
      </div>
      {post.desc && <p className="post-desc">{post.desc}</p>}
      {post.location && <p className="post-location">📍 {post.location}</p>}
      {post.taggedFriends?.length > 0 && (
        <p className="post-tagged">
          Tagged: {post.taggedFriends.map((f) => f.name).join(', ')}
        </p>
      )}
      {post.media ? (
        <div className="post-media">
          {post.media.match(/\.(mp4|mov)$/i) ? (
            <video
              src={getMediaUrl(post.media)}
              controls
              className="media"
              style={{ border: '2px solid red' }}
              onError={(e) => {
                console.error(`Post: Video load error for post ${post._id}:`, e);
                e.target.poster = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
              }}
            />
          ) : post.media.match(/\.(mp3|wav)$/i) ? (
            <audio
              src={getMediaUrl(post.media)}
              controls
              className="media"
              style={{ border: '2px solid red' }}
              onError={(e) => {
                console.error(`Post: Audio load error for post ${post._id}:`, e);
              }}
            />
          ) : (
            <img
              src={getMediaUrl(post.media)}
              alt="Post media"
              className="media"
              style={{ border: '2px solid red' }}
              onError={(e) => {
                console.error(`Post: Image load error for post ${post._id}:`, e);
                e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
                e.target.alt = 'Failed to load image';
              }}
            />
          )}
        </div>
      ) : (
        post.media && <p className="post-media-error">Media not available</p>
      )}
      {error && <p className="error">{error}</p>}
      <div className="post-actions">
        <div className="like-section">
          <button
            className={`like-btn ${post.likedBy?.includes(currentUser._id) ? 'liked' : ''}`}
            onClick={handleLike}
            disabled={!currentUser}
          >
            {post.likedBy?.includes(currentUser._id) ? 'Unlike' : 'Like'}
          </button>
          <span className="like-count">{post.likes || 0} likes</span>
        </div>
        <div className="comment-section">
          <form onSubmit={handleCommentSubmit}>
            <input
              type="text"
              placeholder="Add a comment..."
              value={commentInput}
              onChange={(e) => setCommentInput(e.target.value)}
              disabled={!currentUser}
            />
            <button type="submit" disabled={!currentUser || !commentInput.trim()}>
              Post
            </button>
          </form>
          {post.comments?.length > 0 && (
            <div className="comments-list">
              {post.comments.map((comment) => (
                <div key={comment._id} className="comment">
                  <span className="comment-user">{comment.userId?.name || 'Unknown'}</span>
                  <span className="comment-content">{comment.content}</span>
                  <span className="comment-timestamp">
                    {new Date(comment.createdAt).toLocaleString()}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Post;
